const repo = "acme/cli";
let total = 0;
let page = 1;
const shapes: string[] = [];
while (page <= 100) {
  const res: any = await tools.list_issues({ repo, state: "closed", page });
  let items: any[];
  if (Array.isArray(res)) items = res;
  else if (res && Array.isArray(res.items)) items = res.items;
  else if (res && Array.isArray(res.issues)) items = res.issues;
  else if (res && Array.isArray(res.data)) items = res.data;
  else {
    return { error: "unexpected shape", sample: JSON.stringify(res).slice(0, 1000) };
  }
  if (page === 1) shapes.push(JSON.stringify(Object.keys(res && !Array.isArray(res) ? res : items[0] ?? {})).slice(0, 300));
  // Exclude pull requests if they appear in the issues listing
  const issuesOnly = items.filter((i: any) => !(i && (i.pull_request || i.is_pull_request || i.isPullRequest)));
  total += issuesOnly.length;
  if (items.length < 50) break;
  page++;
}
return { repo, closedIssues: total, pages: page, shapes };
