const repo = "acme/cli";
let total = 0;
let rawCount = 0;
let page = 1;
const itemKeys = new Set<string>();
let lastNext: unknown = null;
let prLike = 0;
while (page <= 100) {
  const res: any = await tools.list_issues({ repo, state: "closed", page });
  const items: any[] = res.items ?? [];
  lastNext = res.next_page;
  for (const i of items) {
    Object.keys(i ?? {}).forEach((k) => itemKeys.add(k));
    rawCount++;
    if (i && (i.pull_request || i.is_pull_request || i.isPullRequest || i.pr || i.html_url?.includes?.("/pull/"))) prLike++;
  }
  total += items.length;
  if (!res.next_page || items.length === 0) break;
  page++;
}
return { repo, rawCount, prLike, pages: page, lastNext, itemKeys: [...itemKeys] };
